dtsPropsFor.FigureTable:
/** Column headers. Omit the leading blank — it is added for the label column. */
columns?: string[];
/** One row per figure. Numbers render as money; strings render verbatim. */
rows: Array<{
  label: string;
  /** Caption under the label — the "why" for a figure that needs one. */
  note?: string;
  /** One value per column. */
  values: (number | string)[];
  /** 'out' is money leaving; 'net' is reserved for the take-home result. */
  tone?: 'default' | 'out' | 'net' | 'muted';
  /** 'always-negative' forces the minus on money-out rows held as positives. */
  sign?: 'auto' | 'always-negative' | 'none';
  /** Rule above and heavier weight — the Net or Taxed on line. */
  total?: boolean;
  /** The working behind this row; the label becomes an inspect control. */
  derivation?: Array<{ label: string; note?: string; values: (number | string)[]; tone?: 'default' | 'out' | 'net' | 'muted'; sign?: 'auto' | 'always-negative' | 'none'; total?: boolean }>;
}>;
/** Accessible name, e.g. "Fortnight with and without overtime". */
caption: string;

dtsPropsFor.InspectableFigure:
value: number;
/** Names the figure for screen readers: "PAYG tax". */
label: string;
/** The working, shown when expanded. */
derivation: Array<{ label: string; note?: string; values: (number | string)[]; tone?: 'default' | 'out' | 'net' | 'muted'; sign?: 'auto' | 'always-negative' | 'none'; total?: boolean }>;
tone?: 'default' | 'out' | 'net' | 'muted';
size?: 'inline' | 'display';
sign?: 'auto' | 'always-negative' | 'none';
currency?: boolean;
